package jp.reader.manga;
import java.io.*;import java.util.zip.*;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;
public class TestMain {
 static void check(boolean x,String label){if(!x)throw new AssertionError(label);System.out.println("PASS "+label);}
 static byte[] jpeg(int w,int h)throws Exception{BufferedImage b=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);ByteArrayOutputStream o=new ByteArrayOutputStream();ImageIO.write(b,"jpg",o);return o.toByteArray();}
 static byte[] zip()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){for(String n:new String[]{"page10.jpg","page2.jpg","page1.jpg","cover.jpeg","__MACOSX/._page1.jpg"}){z.putNextEntry(new ZipEntry(n));z.write(jpeg(n.equals("cover.jpeg")?300:100,n.equals("cover.jpeg")?100:200));z.closeEntry();}z.putNextEntry(new ZipEntry("filler.dat"));byte[] random=new byte[500000];new java.util.Random(9).nextBytes(random);z.write(random);z.closeEntry();}return out.toByteArray();}
 public static void main(String[] args)throws Exception{byte[] file=zip();Dav d=new Dav(file);RemoteZip z=new RemoteZip(d,"test");check(z.pages.size()==4,"JPEG以外とmacOS付加ファイルを除外");check(z.pages.get(0).name.equals("cover.jpeg")&&z.pages.get(1).name.equals("page1.jpg")&&z.pages.get(2).name.equals("page2.jpg")&&z.pages.get(3).name.equals("page10.jpg"),"ページ番号の自然順");android.graphics.Bitmap cover=z.bitmap(0,1000,1000),page=z.bitmap(1,1000,1000);check(cover.getWidth()>cover.getHeight(),"横長画像の判定に必要な寸法取得");check(page.getWidth()<page.getHeight(),"縦長JPEGの展開と寸法取得");check(d.transferred<file.length,"ZIP全体を取得せずに読込");try{new RemoteZip(new Dav("notzip".getBytes()),"x");throw new AssertionError("不正ZIP");}catch(IOException e){System.out.println("PASS 不正ZIPはエラー");}java.util.List<Dav.Item> entries=new java.util.ArrayList<>();entries.add(new Dav.Item("u10","vol10.zip",false));entries.add(new Dav.Item("dir","folder",true));entries.add(new Dav.Item("u2","vol2.zip",false));entries.add(new Dav.Item("u1","vol1.zip",false));check(NextBook.find(entries,"u1").url.equals("u2"),"次巻は自然順で選択");check(NextBook.find(entries,"u10")==null && NextBook.find(entries,"unknown")==null,"最終巻・不明ファイルでは先読みなし");check(!NextBook.reachedThreshold(89,100)&&NextBook.reachedThreshold(90,100)&&NextBook.reachedThreshold(91,100),"90％で先読み開始");System.out.println("転送="+d.transferred+" bytes / ZIP="+file.length+" bytes"); }
}
